A Gaussian 2-user multiple access channel (MAC) and a Gaussian point-to-point (P2P) channel use the same medium for their communication. They interfere with each other as shown in Figure \ref{pIMAC}. We call the resulting setup the PIMAC, whose received signals can be written as
\begin{align}
Y_1&=X_1+X_2+h_{31}X_3+Z_1,\\
Y_2&=h_{12}X_1+h_{22}X_2+X_3+Z_2,
\end{align}
where $h_{ij}\in\mathbb{R}$ denotes the channel coefficient from transmitter $i\in\{1,2,3\}$ to receiver $j\in\{1,2\}$, $X_i$ is the transmit symbol of transmitter $i$ and $Z_j$ is an additive white Gaussian noise (AWGN) with $Z_j\sim\mathcal{N}(0,1)$.

An $(n,2^{nR_1},2^{nR_2},2^{nR_3})$ code for the PIMAC consists of encoding functions, decoding functions, and message sets, and induces an average probability of decoding error given by 
\begin{align}
P^{(n)}=\frac{1}{2^{nR_\Sigma}}\sum_{\vec{m}\in\mathcal{M}_1\times\mathcal{M}_2\times\mathcal{M}_3}P\left(\bigcup_{i=1}^3E_i\right),
\end{align}
where $R_\Sigma=\sum_{i=1}^3R_i$ and $\vec{m}=(m_1,m_2,m_3)$.

The closure of the set of all achievable rates is the capacity region of the PIMAC denoted $\mathcal{C}$, and the sum capacity is the highest achievable sum-rate 
\begin{align}
C_\Sigma=\max_{(R_1,R_2,R_3)\in\mathcal{C}}R_\Sigma.
\end{align}

We denote a multiple access channel MAC from transmitters $i\in\mathcal{S}\subseteq\{1,2,3\}$ to receiver $j\in\{1,2\}$ with AWGN with variance $1$ by $M(\mathcal{S},j)$ and its corresponding capacity region by $\mathcal{C}^M(\mathcal{S},j)$. This region is given by
\begin{equation*}
\mathcal{C}^M(\mathcal{S},j)=\left\{
\begin{array}{l}
R_i\geq0\ \ \forall i \in \mathcal{S}: \forall \mathcal{T}\subseteq\mathcal{S}\\
\sum_{i\in\mathcal{T}}R_i\leq\frac{1}{2}\log\left(1+\sum_{i\in\mathcal{T}}h_{ij}^2P_i\right)
\end{array}
\right\}.
\end{equation*}

The capacity region of the PIMAC is outer bounded by $\overline{\mathcal{C}}$, $$\mathcal{C}\subseteq\overline{\mathcal{C}}$$ where
\begin{align*}
\overline{\mathcal{C}}=\left\{
\begin{array}{lr}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:&\\
R_3\leq\frac{1}{2}\log(1+P_3)&\\
(R_1,R_2)\in\mathcal{C}^M(\{1,2\},1)&\\
(R_1,R_3)\in\mathcal{C}_M(\{1,3\},2)& \text{ if } h_{12}^2\geq1\\
(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)& \text{ if } h_{22}^2\geq1\\
(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},1)& \text{ if } h_{31}^2\geq1
\end{array}\right\}.
\end{align*}

The capacity region of the PIMAC is inner bounded by $\underline{\mathcal{C}}$, $$\underline{\mathcal{C}}\subseteq\mathcal{C}$$
where
\begin{align}
\underline{\mathcal{C}}=\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},1)\\
(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},2)
\end{array}\right\}.
\end{align}

If the PIMAC satisfies the following conditions
\begin{align} h_{12}^2,h_{22}^2,h_{31}^2&\geq1\\ h_{12}^2P_1+h_{22}^2P_2+P_3&\geq P_1+P_2+h_{31}^2P_3,
\end{align}
then the outer bound $\overline{\mathcal{C}}$ and the inner bound $\underline{\mathcal{C}}$ coincide and hence, the capacity region of the PIMAC is
\begin{align}
\mathcal{C}=\overline{\mathcal{C}}=\underline{\mathcal{C}}.
\end{align}

Since $h_{12}^2\geq1+P_3+h_{22}^2P_2\geq1+P_3$, then it can be shown that the bound (\ref{SIB3}) is redundant and can be removed. Thus the outer bound becomes
\begin{align}
\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)\\
(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},1)
\end{array}\right\}.
\end{align} 
Moreover $h_{12}^2\geq1+P_3+h_{22}^2P_2\Rightarrow$
\begin{align}
\frac{1}{2}\log\left(1+\frac{h_{12}^2P_1}{1+P_3+h_{22}^2P_2}\right)\geq\frac{1}{2}\log(1+P_1).
\end{align}
This means that the second receiver can decode $X_1^n$ while treating $X_2^n$ and $X_3^n$ as noise without imposing an additional rate constraint on the achievable rates. Then by subtracting the contribution of $X_1^n$ from $Y_2^n$, and decoding $X_2^n$ and $X_3^n$ in a MAC fashion at the second receiver, the rate region $\mathcal{C}^M(\{2,3\},2)$ can be achieved. If the first receiver decodes all signals in a MAC fashion, the rate region $\mathcal{C}_M(\{1,2,3\},1)$ can be achieved. Therefore we have the following theorem.

Since $h_{12}^2\geq1+P_3+h_{22}^2P_2\geq1+P_3$, then it can be shown that the bound (\ref{SIB3}) is redundant and can be removed. Thus the outer bound becomes
\begin{align}
\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)\\
(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},1)
\end{array}\right\}.
\end{align}

Moreover $h_{12}^2\geq1+P_3+h_{22}^2P_2\Rightarrow$
\begin{align}
\frac{1}{2}\log\left(1+\frac{h_{12}^2P_1}{1+P_3+h_{22}^2P_2}\right)\geq\frac{1}{2}\log(1+P_1).
\end{align}
This means that the second receiver can decode $X_1^n$ while treating $X_2^n$ and $X_3^n$ as noise without imposing an additional rate constraint on the achievable rates.

If the PIMAC satisfies (\ref{VSI12-1})-(\ref{VSI12-3}) then its capacity region is
\begin{align}
\mathcal{C}=\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)\\
(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},1)
\end{array}\right\}.
\end{align}

In this case, the rate restriction (\ref{SIB5}) can be replaced with
\begin{align}
(R_1,R_2)&\in\mathcal{C}_M(\{1,2\},1),
\end{align}
which follows since the rate upper bounds on $R_3$, $R_1+R_3$, $R_2+R_3$, and $R_1+R_2+R_3$ are all redundant given $(R_1,R_3)\in\mathcal{C}_M(\{1,3\},2)$ and $(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)$. Therefore, the following capacity outer bound holds
\begin{align}
\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
(R_1,R_3)\in\mathcal{C}_M(\{1,3\},2)\\
(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)\\
(R_1,R_2)\in\mathcal{C}_M(\{1,2\},1)
\end{array}\right\}.
\end{align} 


This outer bound can be achieved if we add one more condition on the PIMAC as we show next. If (\ref{VSI31-3}) holds then receiver 1 can decode $X_3^n$ while treating $X_1^n$ and $X_2^n$ as noise without imposing an additional rate constraint on $m_3$. This follows since (\ref{VSI31-3}) $\Rightarrow$
\begin{align}
\frac{1}{2}\log\left(1+\frac{h_{31}^2P_3}{1+P_1+P_2}\right)\geq\frac{1}{2}\log(1+P_3).
\end{align}
Thus, receiver 1 can remove the contribution of $X_3^n$ from $Y_1^n$ and then decode $X_1^n$ and $X_2^n$ achieving $\mathcal{C}^M(\{1,2\},1)$. Let receiver 2 decode all signals in a MAC fashion achieving the region $(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},2)$. If we have
\begin{align} h_{12}^2P_1+h_{22}^2P_2\geq(P_1+P_2)(1+P_3),
\end{align}
then the bound on $R_1+R_2+R_3$ in $\mathcal{C}_M(\{1,2,3\},2)$ becomes redundant and can be removed. This follows since
\begin{align}
&h_{12}^2P_1+h_{22}^2P_2\geq(P_1+P_2)(1+P_3)\Rightarrow\\
&\frac{1}{2}\log(1+h_{12}^2P_1+h_{22}^2P_2+P_3)\geq\frac{1}{2}\log(1+P_1+P_2)\nonumber\\
&\hspace{5cm}+\frac{1}{2}\log(1+P_3).
\end{align}
Thus, under condition (\ref{VSI31-4}) and given $(R_1,R_2)\in\mathcal{C}^M(\{1,2\},1)$ we can replace $(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},2)$ by 
\begin{align}
(R_1,R_2)&\in\mathcal{C}_M(\{1,2\},2)\\
(R_1,R_3)&\in\mathcal{C}_M(\{1,3\},2)\\
(R_2,R_3)&\in\mathcal{C}_M(\{2,3\},2).
\end{align}
Now, since the region $\mathcal{C}_M(\{1,2\},2)$ is larger than $\mathcal{C}_M(\{1,2\},1)$, we obtain the following theorem.

In this case, the rate restriction (\ref{SIB5}) can be replaced with
\begin{align}
(R_1,R_2)&\in\mathcal{C}_M(\{1,2\},1),
\end{align}
which follows since the rate upper bounds on $R_3$, $R_1+R_3$, $R_2+R_3$, and $R_1+R_2+R_3$ are all redundant given $(R_1,R_3)\in\mathcal{C}_M(\{1,3\},2)$ and $(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)$. Therefore, the following capacity outer bound holds
\begin{align}
\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
(R_1,R_3)\in\mathcal{C}_M(\{1,3\},2)\\
(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)\\
(R_1,R_2)\in\mathcal{C}_M(\{1,2\},1)
\end{array}\right\}.
\end{align}

This outer bound can be achieved if we add one more condition on the PIMAC as we show next. If (\ref{VSI31-3}) holds then receiver 1 can decode $X_3^n$ while treating $X_1^n$ and $X_2^n$ as noise without imposing an additional rate constraint on $m_3$. This follows since (\ref{VSI31-3}) $\Rightarrow$
\begin{align}
\frac{1}{2}\log\left(1+\frac{h_{31}^2P_3}{1+P_1+P_2}\right)\geq\frac{1}{2}\log(1+P_3).
\end{align}
Thus, receiver 1 can remove the contribution of $X_3^n$ from $Y_1^n$ and then decode $X_1^n$ and $X_2^n$ achieving $\mathcal{C}^M(\{1,2\},1)$.

Let receiver 2 decode all signals in a MAC fashion achieving the region $(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},2)$. If we have
\begin{align} h_{12}^2P_1+h_{22}^2P_2\geq(P_1+P_2)(1+P_3),
\end{align}
then the bound on $R_1+R_2+R_3$ in $\mathcal{C}_M(\{1,2,3\},2)$ becomes redundant and can be removed. This follows since
\begin{align}
&h_{12}^2P_1+h_{22}^2P_2\geq(P_1+P_2)(1+P_3)\Rightarrow\\
&\frac{1}{2}\log(1+h_{12}^2P_1+h_{22}^2P_2+P_3)\geq\frac{1}{2}\log(1+P_1+P_2)\nonumber\\
&\hspace{5cm}+\frac{1}{2}\log(1+P_3).
\end{align}
Thus, under condition (\ref{VSI31-4}) and given $(R_1,R_2)\in\mathcal{C}^M(\{1,2\},1)$ we can replace $(R_1,R_2,R_3)\in\mathcal{C}_M(\{1,2,3\},2)$ by 
\begin{align}
(R_1,R_2)&\in\mathcal{C}_M(\{1,2\},2)\\
(R_1,R_3)&\in\mathcal{C}_M(\{1,3\},2)\\
(R_2,R_3)&\in\mathcal{C}_M(\{2,3\},2).
\end{align}

If the PIMAC satisfies (\ref{VSI31-1})-(\ref{VSI31-3}) and (\ref{VSI31-4}), then its capacity region is
\begin{align}
\mathcal{C}=\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
(R_1,R_3)\in\mathcal{C}_M(\{1,3\},2)\\
(R_2,R_3)\in\mathcal{C}_M(\{2,3\},2)\\
(R_1,R_2)\in\mathcal{C}_M(\{1,2\},1)
\end{array}\right\}.
\end{align}

Consider now the PIMAC with very strong interference such that
\begin{align} h_{12}^2,h_{22}^2&\geq1+P_3\\ h_{31}^2&\geq1+P_1+P_2.
\end{align}

Clearly, the following outer bound holds for the PIMAC
\begin{align}
\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
R_3\leq\frac{1}{2}\log(1+P_3)\\
(R_1,R_2)\in\mathcal{C}_M(\{1,2\},1)
\end{array}\right\}.
\end{align}
This outer bound can be achieved under the given conditions (\ref{pIMAC-VSI1}) and (\ref{pIMAC-VSI2}) by decoding interference first at each receiver while treating the desired signal as noise, and then decoding the desired signal after removing the contribution of interference. Thus, as if interference is not present, the capacity region of the pIMAC becomes as given in the following theorem.

Clearly, the following outer bound holds for the PIMAC
\begin{align}
\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
R_3\leq\frac{1}{2}\log(1+P_3)\\
(R_1,R_2)\in\mathcal{C}_M(\{1,2\},1)
\end{array}\right\}.
\end{align}

If the PIMAC satisfies (\ref{pIMAC-VSI1}) and (\ref{pIMAC-VSI2}), then its capacity region is
\begin{align}
\mathcal{C}=\left\{
\begin{array}{l}
(R_1,R_2,R_3)\in\mathbb{R}_+^3:\\
R_3\leq\frac{1}{2}\log(1+P_3)\\
(R_1,R_2)\in\mathcal{C}_M(\{1,2\},1)
\end{array}\right\}.
\end{align}

The sum capacity of the PIMAC is upper bounded by $\overline{C}_\Sigma$, i.e. $$C_\Sigma\leq\overline{C}_\Sigma$$ where
\begin{align}
\overline{C}_\Sigma&\triangleq\min_{\substack{|\rho_1|,|\rho_2|\leq1,\\
\eta_1^2\leq1-\rho_2^2,\\
\eta_2^2\leq1-\rho_1^2}} I(X_{1G},X_{2G};Y_{1G},S_{1G})+I(X_{3G};Y_{2G},S_{2G})
\end{align}
with $X_{iG}\sim\mathcal{N}(0,P_i)$, $Y_{iG}$ is the corresponding channel output when the input is $X_{iG}$ and 
\begin{align}
S_{1G}&=h_{12}X_{1G}+h_{22}X_{2G}+\eta_1W_1\\
S_{2G}&=h_{31}X_{3G}+\eta_2W_2,
\end{align}
where $W_i\sim\mathcal{N}(0,1)$ for $i\in\{1,2\}$ such that $\mathbb{E}[W_iZ_i]=\rho_i$.

Clearly, for any achievable rate triple $(R_1,R_2,R_3)$, the rate $R_3$ is upper bounded by the interference free capacity of the P2P channel, and the rate couple $(R_1,R_2)$ is included in the  capacity region of the interference free MAC $M(\{1,2\},1)$, i.e. 
\begin{align}
R_3&\leq\frac{1}{2}\log(1+P_3)\\
(R_1,R_2)&\in\mathcal{C}^{M}(\{1,2\},1).
\end{align}

Now we derive the other bounds. A genie gives $m_2$ as additional information to the second receiver. The obtained genie aided channel has a larger capacity region than the original PIMAC and can be used to outer bound $\mathcal{C}$. Now consider a rate tuple $(R_1,R_2,R_3)$ in the capacity region of the genie aided channel. This means that the first receiver and the second receiver are able to decode $(m_1,m_2)$ and $m_3$ reliably respectively. Since the second receiver is able to decode $m_3$, and since it knows $m_2$ from the genie, then it is able to construct 
\begin{align}
\tilde{Y}_1^n&=\frac{Y_2^n-h_{22}X_2^n-X_3^n}{h_{12}}+X_2^n+h_{31}X_3^n\nonumber\\
&=X_1^n+X_2^n+h_{31}X_3^n+\frac{1}{h_{12}}Z_2^n
\end{align}
If $h_{12}^2\geq1$, then $\tilde{Y}_1^n$ is a less noisy version of $Y_1^n$. So if the first receiver is able to decode $m_1$ then so does the second receiver. Thus
$(R_1,R_3)$ is contained in the MAC region of $M(\{2,3\},2)$, i.e. 
\begin{align}
(R_1,R_3)\in\mathcal{C}^{M}(\{1,3\},2)  \text{ if } h_{12}^2\geq1.
\end{align}
Similarly, we can show that
\begin{align}
(R_2,R_3)\in\mathcal{C}^{M}(\{2,3\},2) &\text{ if } h_{22}^2\geq1.
\end{align}
Finally, for any rate triple $(R_1,R_2,R_3)\in\mathcal{C}$, the first receiver is able to decode $m_1$ and $m_2$ reliably. Thus, if $h_{31}^2\geq1$, receiver 1 can construct a less noisy version of $Y_2^n$ and then decode $m_3$ reliably leading to the bound
\begin{align}
(R_1,R_2,R_3)\in\mathcal{C}^{M}(\{1,2,3\},1) &\text{ if } h_{31}^2\geq1.
\end{align}
and the statement of the Lemma is proved.

Clearly, for any achievable rate triple $(R_1,R_2,R_3)$, the rate $R_3$ is upper bounded by the interference free capacity of the P2P channel, and the rate couple $(R_1,R_2)$ is included in the  capacity region of the interference free MAC $M(\{1,2\},1)$, i.e. 
\begin{align}
R_3&\leq\frac{1}{2}\log(1+P_3)\\
(R_1,R_2)&\in\mathcal{C}^{M}(\{1,2\},1).
\end{align}

Now consider a rate tuple $(R_1,R_2,R_3)$ in the capacity region of the genie aided channel. This means that the first receiver and the second receiver are able to decode $(m_1,m_2)$ and $m_3$ reliably respectively. Since the second receiver is able to decode $m_3$, and since it knows $m_2$ from the genie, then it is able to construct 
\begin{align}
\tilde{Y}_1^n&=\frac{Y_2^n-h_{22}X_2^n-X_3^n}{h_{12}}+X_2^n+h_{31}X_3^n\nonumber\\
&=X_1^n+X_2^n+h_{31}X_3^n+\frac{1}{h_{12}}Z_2^n
\end{align}

If $h_{12}^2\geq1$, then $\tilde{Y}_1^n$ is a less noisy version of $Y_1^n$. So if the first receiver is able to decode $m_1$ then so does the second receiver. Thus
$(R_1,R_3)$ is contained in the MAC region of $M(\{2,3\},2)$, i.e. 
\begin{align}
(R_1,R_3)\in\mathcal{C}^{M}(\{1,3\},2)  \text{ if } h_{12}^2\geq1.
\end{align}

Similarly, we can show that
\begin{align}
(R_2,R_3)\in\mathcal{C}^{M}(\{2,3\},2) &\text{ if } h_{22}^2\geq1.
\end{align}

Finally, for any rate triple $(R_1,R_2,R_3)\in\mathcal{C}$, the first receiver is able to decode $m_1$ and $m_2$ reliably. Thus, if $h_{31}^2\geq1$, receiver 1 can construct a less noisy version of $Y_2^n$ and then decode $m_3$ reliably leading to the bound
\begin{align}
(R_1,R_2,R_3)\in\mathcal{C}^{M}(\{1,2,3\},1) &\text{ if } h_{31}^2\geq1.
\end{align}
and the statement of the Lemma is proved.

Consider the following signals
\begin{align}
S_1^n&=h_{12}X_1^n+h_{22}X_2^n+\eta_1W_1^n\\
S_2^n&=h_{31}X_3^n+\eta_2W_2^n
\end{align}
where $\eta_i\in\mathbb{R}$ and $W_i^n$ is an i.i.d. sequence with $W_i\sim\mathcal{N}(0,1)$ for $i\in\{1,2\}$ such that $\mathbb{E}[W_iZ_i]=\rho_i$. A genie gives these signals as extra information to the receivers. Thus, receiver $i$ knows both $Y_i^n$ and $S_i^n$ and uses them for decoding. Using Fano's inequality, we have
\begin{align}
n(R_1+R_2)&\leq I(X_1^n,X_2^n;Y_1^n,S_1^n)+n\epsilon_{1n}\\
nR_3&\leq I(X_3^n;Y_2^n,S_2^n)+n\epsilon_{2n}
\end{align}
where $\epsilon_{1n},\epsilon_{2n}\to0$ as $n\to\infty$. Using the chain rule, we can write
\begin{align}
n(R_1+R_2-\epsilon_{1n})&\leq I(X_1^n,X_2^n;S_1^n)+I(X_1^n,X_2^n;Y_1^n|S_1^n)\nonumber\\
&=h(S_1^n)-h(S_1^n|X_1^n,X_2^n)+h(Y_1^n|S_1^n)\nonumber\\ &\quad-h(Y_1^n|S_1^n,X_1^n,X_2^n).
\end{align}
Similarly
\begin{align}
n(R_3-\epsilon_{2n})&\leq h(S_2^n)-h(S_2^n|X_3^n)+h(Y_2^n|S_2^n)\nonumber\\ &\quad-h(Y_2^n|S_2^n,X_3^n).
\end{align}
The next step is to show that sum of the above quantities (\ref{Q1}) and (\ref{Q2}) are maximized when $X_i^n$ is i.i.d. Gaussian for all $i\in\{1,2,3\}$, i.e. $X_i\sim\mathcal{N}(0,P_i^*)$ where $P_i^*\leq P_i$. We will denote that Gaussian $X_i$ as $X_{iG}$ and the corresponding outputs as $Y_{iG}$ and $S_{iG}$. Since the Gaussian distribution maximizes the conditional differential entropy under a covariance constraint, we have
\begin{align}
h(Y_1^n|S_1^n)&\leq nh(Y_{1G}|S_{1G})\\
h(Y_2^n|S_2^n)&\leq nh(Y_{2G}|S_{2G}).
\end{align}
Furthermore, the terms $h(S_1^n|X_1^n,X_2^n)$ and $h(S_2^n|X_3^n)$ are independent of the distribution of $X_i$. Now, we jointly maximize the difference $h(S_1^n)-h(Y_2^n|S_2^n,X_3^n)$ as follows
\begin{align}
&\hspace{-1cm}h(S_1^n)-h(Y_2^n|S_2^n,X_3^n)\nonumber\\
&=h(h_{12}X_1^n+h_{22}X_2^n+\eta_1W_1^n)\nonumber\\
&\quad-h(h_{12}X_1^n+h_{22}X_2^n+Z_2^n|W_2^n)\\
&\stackrel{(a)}{=}h(h_{12}X_1^n+h_{22}X_2^n+\eta_1W_1^n)\nonumber\\
&\quad-h(h_{12}X_1^n+h_{22}X_2^n+V_2^n)\\
&\stackrel{(b)}{\leq}nh(h_{12}X_{1G}+h_{22}X_{2G}+\eta_1W_1)\nonumber\\
&\quad-nh(h_{12}X_{1G}+h_{22}X_{2G}+V_2)\\ &=nh(S_{1G})-nh(Y_{2G}|S_{2G},X_{3G},X_{4G}),
\end{align}
where $(a)$ follows from \cite[Lemma 6]{AnnapureddyVeeravalli} with $V_2^n$ being an i.i.d. Gaussian sequence with $V_2\sim\mathcal{N}(0,1-\rho_2^2)$ and $(b)$ from the worst case noise \cite{DiggaviCover} such that $\eta_1^2\leq 1-\rho_2^2$. Since $\eta_1^2\leq1-\rho_2^2$, (\ref{T1}) can be shown to be increasing in $P_1^*$ and $P_2^*$ and thus is maximized by $X_{iG}\sim\mathcal{N}(0,P_i)$. Similarly, if $\eta_2^2\leq1-\rho_1^2$, $h(S_2^n)-h(Y_1^n|S_1^n,X_1^n,X_2^n)$ can be shown to be maximized by $X_{iG}\sim\mathcal{N}(0,P_i)$. Moreover, $h(Y_{1G}|S_{1G})$ and $h(Y_{2G}|S_{2G})$ can be shown to be increasing in $P_i^*$ and thus also maximized by $X_{iG}\sim\mathcal{N}(0,P_i)$. As a result, by letting $n\to\infty$
\begin{align} &R_1+R_2+R_3\nonumber\\
&\quad\leq I(X_{1G},X_{2G};Y_{1G},S_{1G})+I(X_{3G};Y_{2G},S_{2G})
\end{align}
with $X_{iG}\sim\mathcal{N}(0,P_i)$ and $\eta_i\leq1-\rho_j^2$.

Consider the following signals
\begin{align}
S_1^n&=h_{12}X_1^n+h_{22}X_2^n+\eta_1W_1^n\\
S_2^n&=h_{31}X_3^n+\eta_2W_2^n
\end{align}
where $\eta_i\in\mathbb{R}$ and $W_i^n$ is an i.i.d. sequence with $W_i\sim\mathcal{N}(0,1)$ for $i\in\{1,2\}$ such that $\mathbb{E}[W_iZ_i]=\rho_i$. A genie gives these signals as extra information to the receivers. Thus, receiver $i$ knows both $Y_i^n$ and $S_i^n$ and uses them for decoding.

Using Fano's inequality, we have
\begin{align}
n(R_1+R_2)&\leq I(X_1^n,X_2^n;Y_1^n,S_1^n)+n\epsilon_{1n}\\
nR_3&\leq I(X_3^n;Y_2^n,S_2^n)+n\epsilon_{2n}
\end{align}
where $\epsilon_{1n},\epsilon_{2n}\to0$ as $n\to\infty$.

Using the chain rule, we can write
\begin{align}
n(R_1+R_2-\epsilon_{1n})&\leq I(X_1^n,X_2^n;S_1^n)+I(X_1^n,X_2^n;Y_1^n|S_1^n)\nonumber\\
&=h(S_1^n)-h(S_1^n|X_1^n,X_2^n)+h(Y_1^n|S_1^n)\nonumber\\ &\quad-h(Y_1^n|S_1^n,X_1^n,X_2^n).
\end{align}
Similarly
\begin{align}
n(R_3-\epsilon_{2n})&\leq h(S_2^n)-h(S_2^n|X_3^n)+h(Y_2^n|S_2^n)\nonumber\\ &\quad-h(Y_2^n|S_2^n,X_3^n).
\end{align}

Since the Gaussian distribution maximizes the conditional differential entropy under a covariance constraint, we have
\begin{align}
h(Y_1^n|S_1^n)&\leq nh(Y_{1G}|S_{1G})\\
h(Y_2^n|S_2^n)&\leq nh(Y_{2G}|S_{2G}).
\end{align}
